\caption{$\mathrm{Coreset}3(X,A,r,k,\varepsilon)$}
\label{alg_coreset3}
\begin{algorithmic}[1]
	\REQUIRE An $(r,k)$-instance $X$, $A\in \binom{\mathbb{R}^d}{k}$,  and $\varepsilon$.
	\ENSURE Coreset $D$
	\STATE $s\gets \min(k^{4/3} \varepsilon^{-2}, k \varepsilon^{-3})\cdot \log^{O(1)}(k/\varepsilon)$ \label{alg_coreset3_size}
	\FOR{$x\in X$}
	\STATE $p(x)\gets \frac{1}{4}\big(\frac{\cost(x,A)+\Delta_{\pi(x)}}{\cost(X,A)}+\frac{1}{k|X_{\pi(x)}|}+\frac{\cost(x,A)}{k\cost(X_{\pi(x)},A)}\big)$
	\ENDFOR
	\STATE
	Draw with replacement a sample $U$ of $s$ points from $X$ where $x\in X$ is drawn w.p. $p(x)$, and weighted by $w_U(x)=\frac{1}{s\cdot p(x)}$ if drawn
	\FOR{$i=1,\dots,k$}
	\STATE $u_i\gets \|U\cap X_i\|_1$
	\ENDFOR
	\FOR{$x\in U$}
	\STATE add $x$ into $D$ with weight $w_D(x)=\frac{|X_{\pi(x)}|}{u_{\pi(x)}}\cdot w_U(x)$ 
	\label{alg3_scale}
	\ENDFOR
	\RETURN $D$
\end{algorithmic}


