    \ensuremath{\mathbb{E}}\sup_{J,C} \frac{1}{s}\cdot \abs*{ \frac{\sum_{x\in U} v^U_{i,J,C}(x)-\ensuremath{\mathbb{E}} \sum_{x\in U} v^U_{i,J,C}(x)}{(1+2^i|J_{i,C}|/k_0)\cdot r} }
    \lesssim \frac{\varepsilon}{\log^2 \frac{1}{\varepsilon}\cdot \log \frac{k}{\varepsilon}\cdot \log mk},
\end{eqnarray}
then use Markov's inequality and take a union bound.

To ease the notation, let $\gamma_{i,J,C} = 1/(1+2^i|J_{i,C}|/k_0)$. The standard symmetrization trick gives that
\begin{equation}\label{eqn:chaining_error_symmetrization}
\ensuremath{\mathbb{E}}\sup_{J,C} \frac{\gamma_{i,J,C}}{rs}  \abs*{ \sum_{x\in U} v^U_{i,J,C}(x)-\ensuremath{\mathbb{E}} \sum_{x\in U} v^U_{i,J,C}(x) } 
\lesssim
\ensuremath{\mathbb{E}}_U \ensuremath{\mathbb{E}}_g \frac{1}{s} \sup_{J,C} \frac{\gamma_{i,J,C}}{r} \abs*{ \sum_{x\in U} g_x v^U_{i,J,C}(x) }
\end{equation}

For each $h\geq 0$, let $N_{2^{-h},i}^U$ be a ($2^{-h}$)-net of $V_i^U$ satisfying that
\[
    \log \abs[big]{N_{2^{-h},i}^U} \lesssim 2^h dk \log k \log s.
\]
which is possible by Lemma~\ref{lemma_netsize}. Furthermore, when $h = i$, one can ensure that $N_{2^{-i},i}^U$ consists of piecewise constant vectors.

By the net property, there exists a vector $b_{h,J,C}^U\in N_{2^{-h},i}^U$ such that
\[
|b_{h,J,C}^U(x)-v_{i,J,C}^U(x)|\leq 2^{i+2-h} r,\quad \forall x \in U.
\] 
By writing $v_{i,J,C}^U(x)$ as the following telescoping sum
\[
v_{i,J,C}^U(x)=\sum_{h=i}^{\infty} \big(b_{h+1,J,C}^U(x)-b_{h,J,C}^U(x)\big)+b_{i,J,C}^U(x),
\]
we have
\begin{align}
&\quad\ \ensuremath{\mathbb{E}}_U \ensuremath{\mathbb{E}}_g \frac{1}{s} \sup_{J,C} \frac{\gamma_{i,J,C}}{r}\abs*{ \sum_{x\in U} g_x v^U_{i,J,C}(x) } \notag \\
&\leq \ensuremath{\mathbb{E}}_U \frac{1}{s} \sum_{h=i}^\infty \ensuremath{\mathbb{E}}_g \sup_{J,C} \frac{\gamma_{i,J,C}}{r} \abs*{\sum_{x\in U} g_x (b_{h+1,J,C}^U(x)-b_{h,J,C}^U(x))} 
+ \ensuremath{\mathbb{E}}_U\frac{1}{s}\ensuremath{\mathbb{E}}_g \sup_{J,C} \frac{\gamma_{i,J,C}}{r} \abs*{\sum_{x\in U} g_x \cdot b_{i,J,C}^U(x)} \label{eqn:chaining_error_aux}
\end{align}

\sloppy
We bound the two terms individually, starting with the first term. Consider the sum $\sum_{x\in U} g_x \big(b_{h+1,J,C}^U(x)-b_{h,J,C}^U(x)\big)$. 
Observe that $|b_{h+1,J,C}^U(x)-b_{h,J,C}^U(x)|\lesssim 2^{i-h} r$ and, by the construction of $V_i^U$, there are at most $\|U\cap X_{J_{i,C}} \|_0$ nonzero terms in the summation. Thus, the supremum in the first term is taken over $\abs[\big]{N^U_{2^{-h},i}}$ gaussians, each with a variance at most 
\[
    \gamma_{i,J,C}^2 \cdot 2^{2i-2h}\|U\cap X_{J_{i,C}}\|_0 
    \leq 2^{2i-2h} \sup_{J,C} \gamma_{i,J,C}^2 \|U\cap X_{J_{i,C}}\|_0.
\]
By the inequality for the maximum of Gaussians (Fact~\ref{fact_max_gauss}), we conclude that 
\begin{equation}\label{eqn:chaining_error_first_term_aux}
\begin{aligned}
&\quad\ \ensuremath{\mathbb{E}}_U \frac{1}{s} \sum_{h=i}^\infty \ensuremath{\mathbb{E}}_g \sup_{J,C} \frac{\gamma_{i,J,C}}{r} \abs*{\sum_{x\in U} g_x (b_{h+1,J,C}^U(x)-b_{h,J,C}^U(x))}   \\
&\lesssim  \frac{1}{s}\sum_{h=i}^{\infty} 2^{i-h/2} \cdot \sqrt{dk\log k \log s}\cdot \ensuremath{\mathbb{E}}_U \sup_{J,C} \gamma_{i,J,C}\|U\cap X_{J_{i,C}}\|_0^{1/2}.
\end{aligned}
\end{equation}













We have the following lemma to bound the expected supremum on the right-hand side.
\begin{lemma} \label{lemma_chaining_var1}
It holds that $$
\ensuremath{\mathbb{E}}_U \sup_{J,C} \gamma_{i,J,C}\|U\cap X_{J_{i,C}}\|_0^{1/2} \lesssim \sqrt{\frac{s}{2^i}}
$$
\end{lemma}
\begin{proof}
Recall the event $\mathcal{E}$ defined in \eqref{eq_event}. When $\mathcal{E}$ happens, we have $\norm{U\cap X_\ell}_1 \in (1\pm \varepsilon)\cdot |X_\ell|$ for every $\ell\in [k_0]$, which implies that $\frac{n}{s}\cdot \|U\cap X_{J_{i,C}}\|_0 \in (1\pm\varepsilon) \cdot |X_{J_{i,C}}|$. Since $X$ is an $(r,k_0)$-regular instance, we know that $|X_{J_{i,C}}|\leq \frac{2|J_{i,C}|}{k_0}\cdot n$. It follows that $\|U\cap X_{J_{i,C}}\|_0\leq \frac{4|J_{i,C}|}{k_0}\cdot s$
and

\[
\ensuremath{\mathbb{E}}_U \left[\sup_{J,C}\frac{\|U\cap X_{J_{i,C}}\|^{1/2}_0}{ 1+2^i|J_{i,C}|/k_0} \middle| \mathcal{E}\right]
\leq  \ensuremath{\mathbb{E}} \left[\sup_{J,C}\frac{\|U\cap X_{J_{i,C}}\|^{1/2}_0}{ 2\cdot (2^{i}|J_{i,C}|/k_0)^{1/2}} \middle| \mathcal{E} \right]\\
\lesssim \sqrt{\frac{s}{2^i}}
\]

where the first inequality is by $a^2+b^2\geq 2ab$ and the second inequality is by $\|U\cap X_{J_{i,C}}\|_0\leq \frac{4|J_{i,C}|}{k_0}\cdot s$.

On the other hand, it always holds that
\[
    \sup_{J,C}\frac{\|U\cap X_{J_{i,C}}\|^{1/2}_0}{ 1+2^i|J_{i,C}|/k_0} \leq k_0\sqrt{s}.
\]
Therefore,
\begin{multline*}
\ensuremath{\mathbb{E}}_U \sup_{J,C} \gamma_{i,J,C}\|U\cap X_{J_{i,C}}\|_0^{1/2} = \ensuremath{\mathbb{E}}_U \sup_{J,C}\frac{\|U\cap X_{J_{i,C}}\|^{1/2}_0}{ 1+2^i|J_{i,C}|/k_0}
\leq \sqrt{\frac{s}{2^i}}\cdot \mathbb{P}(\mathcal{E}) + k_0\sqrt{s}\cdot \mathbb{P}(\bar{\mathcal{E}})\\
\leq \sqrt{\frac{s}{2^i}} + k_0\sqrt{s}\cdot \frac{\varepsilon}{sk}
\lesssim \sqrt{\frac{s}{2^i}}.
\end{multline*}
Here, the last inequality follows from the fact that $\frac{1}{2^{i/2}}\geq \frac{1}{2^i}\geq \frac{1}{2^T}\gtrsim \varepsilon$.
\end{proof}

Hence, for the first term in \eqref{eqn:chaining_error_aux}, by plugging Lemma~\ref{lemma_chaining_var1} into \eqref{eqn:chaining_error_first_term_aux}, we obtain that
