&\leq \ensuremath{\mathbb{E}}_g \sup_{J,C} \frac{\sum_{j\in J_{i,C}} \abs*{\sum_{x\in U\cap X_j} g_x \cdot b_{i,J,C}^U(x)}}{2^ir\cdot|J_{i,C}|/k_0} \\
&\leq \ensuremath{\mathbb{E}}_g\sup_{J,C}\max_{j\in J_{i,C}} \abs*{ \frac{\sum_{x\in U\cap X_j} g_x\cdot b_{i,J,C}^U(x)}{2^ir/k_0} }\\
&\leq \ensuremath{\mathbb{E}}_g \sup_{C}\max_{j\in I_{i,C}} \abs*{ \frac{\sum_{x\in U\cap X_j} g_x\cdot b_{i,J,C}^U(x)}{2^ir/k_0} }\\
&= \ensuremath{\mathbb{E}}_g \sup_{C}\max_{j\in I_{i,C}} \abs*{ \sum_{x\in U\cap X_j} g_x }\cdot \frac{k_0\cdot \norm{b_{i,J,C}^U}_{\ell^\infty(X_j)}}{2^ir}. 
\end{align*}
In the above, the third inequality is due to the definition that $J_{i,C}=J\cap I_{i,C}\subseteq I_{i,C}$, and the last equality the fact that $b_{i,J,C}^U(x)$ is a constant over each cluster.

Since $b_{i,J,C}^U(x)\leq v_{i,J,C}^U(x)+4r=\mathrm{dist}(x,C)+4r\lesssim 2^i r$, we can then bound
