We suppose that $D$ is capacity-respecting, an $\varepsilon^z$-range approximation with respect to an $\frac{\varepsilon}{10z}$-smoothed distance function $\delta$, and an $\varepsilon$-indexed-subset cost approximation of $X$. 


Fix a center set $C\in \binom{M}{k}$.

Recall that we define $r^\ast := \inf \{r>0\;\big|\; |B(C,r)\cap X|\geq n-t\}$. 

Note that for any center set \( C \), the outlier sets within \( X \) (or \( D \)) are identical with respect to both \(\cost^{(t)}(X,C)\) and \(\cost_z^{(t)}(X,C)\) (or similarly, \(\cost^{(t)}(D,C)\) and \(\cost_z^{(t)}(D,C)\)).

Thus, we can again partition \([k_0]\) into three sets \(A_1, A_2, A_3\) according to $r^\ast$, each retaining the same geometric properties as stated in Lemma \ref{proof_fact}.

We first have the following lemma that generalizes Lemma \ref{lemma:diffrerence:doubling}.

\begin{lemma}[Cost difference decomposition for $\delta$ for general $z\geq 1$]
\label{lemma:diffrerence:doubling_kzC}
If $D$ is capacity-respecting, it holds that 
\begin{equation*}
	\begin{aligned}
	    \abs{ \cost[t]_z(X,C)-\cost[t]_z(D,C) } &\leq \abs{ \cost_z(X_{A_1},C)-\cost_z(D_{A_1},C) } \\
	    &\quad + \int_{(r^\ast-2r)^+}^{r^\ast+2r} \abs*{ |B^\delta(C,u)\cap X_{A_3}|-\norm[\big]{B^\delta(C,u)\cap D_{A_3}}_1 } z u^{z-1} du \\
	    &\quad +\varepsilon 2^{O(z)}\cost^{(t)}_z(X,C) +\varepsilon 2^{O(z)}\cost[t]_z(D,C) + \varepsilon 2^{O(z)} n r^z.
	\end{aligned}
\end{equation*}
\end{lemma}

\begin{proof}
Let $g=\abs{ X_{A_2}\cap B(C,r^\ast) }$, then $g\leq t$.

Since $\delta$ is an $\frac{\varepsilon}{10z}$-smoothed distance function, we know that for any $x\in X$,
\[
(1-\varepsilon) \mathrm{dist}^z(x,C)\leq (1-\frac{\varepsilon}{10z})^z \mathrm{dist}^z(x,C) \leq \delta^z(x,C) \leq (1+\frac{\varepsilon}{10z})^z \mathrm{dist}^z(x,C) \leq (1+\varepsilon) \mathrm{dist}^z(x,C).
\]

Then using the same argument for Lemma \ref{lemma:diffrerence:doubling}, we obtain the following inequality:
\begin{align*}
\abs{ \cost[t]_z(X,C)-\cost[t]_z(D,C) } &\leq \abs{ \cost_z(X_{A_1},C)-\cost_z(D_{A_1},C) } \\
& \quad + (1+\varepsilon)\abs{ \cost[t-g, \delta]_z(X_{A_3},C)-\cost[t-g, \delta]_z(D_{A_3},C) }.
\end{align*}

Thus, it suffices to prove the following inequality
\begin{align} \label{eq:cost_kzC}
\begin{aligned}
& \quad \abs{ \cost[t-g, \delta]_z(X_{A_3},C)-\cost[t-g, \delta]_z(D_{A_3},C) } \\
\leq & \quad \int_{(r^\ast-2r)^+}^{r^\ast+2r} \abs*{ |B^\delta(C,u)\cap X_{A_3}|-\norm[\big]{B^\delta(C,u)\cap D_{A_3}}_1 } z u^{z-1} du \\
	    &\quad +\varepsilon 2^{O(z)} \cost^{(t)}_z(X,C) +\varepsilon  2^{O(z)} \cost[t]_z(D,C) + \varepsilon 2^{O(z)} n r^z.
\end{aligned}
\end{align}

To prove this, we first note that
	\begin{align*}
    	\cost[t-g,\delta]_z(X_{A_3},C)&= \int_{0}^{\infty} (\abs{X_{A_3}} - (t-g)-\vert B^\delta(C,u)\cap X_{A_3} \vert )^+ z u^{z-1} du, \\
	    \cost[t-g,\delta]_z (D_{A_3},C )&=\int_0^\infty (\norm{D_{A_3}}_1 - (t-g) - \norm{B^\delta(C,u)\cap D_{A_3}}_1)^+ z u^{z-1} du.
	\end{align*}

By a similar argument for Lemma \ref{lemma:diffrerence:doubling}, we obtain that
\begin{align}\label{eq:kzC_0}
\begin{aligned}
& \quad \abs{ \cost[t-g, \delta]_z(X_{A_3},C)-\cost[t-g, \delta]_z(D_{A_3},C) } \\
= & \quad \int_{(1-\frac{\varepsilon}{10z})(r^\ast-2r)^+}^{(1+\frac{\varepsilon}{10z})(r^\ast+2r)} \abs*{ |B^\delta(C,u)\cap X_{A_3}|-\norm[\big]{B^\delta(C,u)\cap D_{A_3}}_1 } z u^{z-1} du \\
\leq & \quad \int_{(r^\ast-2r)^+}^{r^\ast+2r} \abs*{ |B^\delta(C,u)\cap X_{A_3}|-\norm[\big]{B^\delta(C,u)\cap D_{A_3}}_1 } z u^{z-1} du \\
	    &\quad + \left((\abs{X_{A_3}}-(t-g))^+ + (\norm{D_{A_3}}_1 - (t-g))^+ \right) \left((1+\frac{\varepsilon}{10z})^z(r^\ast +2r)^z - (r^\ast +2r)^z \right) \\
        & \quad + \left((\abs{X_{A_3}}-(t-g))^+ + (\norm{D_{A_3}}_1 - (t-g))^+ \right) \left((r^\ast -2r)^z - (1-\frac{\varepsilon}{10z})^z(r^\ast - 2r)^z \right)
\end{aligned}
\end{align}

Note that 
\begin{align*}
\cost^{(t)}_z(X,C) \geq \cost[t-g, \delta]_z(X_{A_3},C) \geq & \ (\abs{X_{A_3}}-(t-g))^+ \cdot ((r^\ast - 2r)^+)^z \\
\cost^{(t)}_z(D,C) \geq \cost[t-g, \delta]_z(D_{A_3},C) \geq & \ \norm{D_{A_3}}_1 - (t-g))^+ \cdot ((r^\ast - 2r)^+)^z.
\end{align*}

Thus, given Inequality \eqref{eq:kzC_0}, it suffices to establish the following inequalities to prove Inequality \eqref{eq:cost_kzC}:
\begin{align*}
(1+\frac{\varepsilon}{10z})^z(r^\ast +2r)^z - (r^\ast + 2r)^z \leq & \ \varepsilon 2^{O(z)} (r^\ast - 2r)^z + \varepsilon 2^{O(z)} r^z \\
(r^\ast -2r)^z - (1-\frac{\varepsilon}{10z})^z(r^\ast - 2r)^z \leq & \ \varepsilon 2^{O(z)} ((r^\ast - 2r)^+)^z + \varepsilon 2^{O(z)} r^z.
\end{align*}

The following inequality follows from 
\[
(1+\frac{\varepsilon}{10z})^z(r^\ast +2r)^z - (r^\ast +2r)^z \leq \varepsilon (r^\ast +2r)^z = \varepsilon (r^\ast-2r + 4r)^z 
\leq  \varepsilon 2^{O(z)} (r^\ast - 2r)^z + \varepsilon 2^{O(z)} r^z,
\]
and the second inequality can be proved similarly.

Thus, we complete the proof of Lemma \ref{lemma:diffrerence:doubling_kzC}.
\end{proof}

